#### Phase 2: Core Infrastructure Implementation

**Step 2.1: Implement Database Provisioning Service**

Create automated service for provisioning tenant databases or schemas:

```csharp
public class DatabaseProvisioningService
{
    private readonly IIsolationStrategySelector _strategySelector;
    private readonly IKeyManagementService _keyManagement;
    private readonly IComplianceValidator _complianceValidator;

    public async Task<ProvisioningResult> ProvisionTenantDatabaseAsync(
        string tenantId, TenantRequirements requirements)
    {
        // Select appropriate isolation strategy
        var strategy = await _strategySelector.SelectStrategyAsync(requirements);

        // Generate tenant-specific encryption keys
        var encryptionKeys = await _keyManagement.GenerateTenantKeysAsync(tenantId);

        // Provision database/schema based on strategy
        var database = strategy switch
        {
            IsolationStrategy.DatabasePerTenant =>
                await ProvisionDedicatedDatabaseAsync(tenantId, encryptionKeys),
            IsolationStrategy.SchemaPerTenant =>
                await ProvisionTenantSchemaAsync(tenantId, encryptionKeys),
            IsolationStrategy.RowLevel =>
                await ConfigureRowLevelSecurityAsync(tenantId),
            _ => throw new NotSupportedException($"Strategy {strategy} not supported")
        };

        // Apply compliance configuration
        await _complianceValidator.ApplyComplianceSettingsAsync(
            database, requirements.ComplianceRequirements);

        // Initialize baseline data
        await InitializeTenantDataAsync(database, tenantId);

        return new ProvisioningResult
        {
            TenantId = tenantId,
            Strategy = strategy,
            ConnectionString = database.ConnectionString,
            EncryptionKeyId = encryptionKeys.PrimaryKeyId
        };
    }
}
```text

**Step 2.2: Implement Tenant-Aware Data Access Layer**

Create data access layer enforcing tenant isolation:

```csharp
public class TenantDataAccessLayer
{
    private readonly ITenantContextManager _contextManager;
    private readonly IConnectionFactory _connectionFactory;
    private readonly IQueryValidator _queryValidator;
    private readonly IAuditLogger _auditLogger;

    public async Task<IEnumerable<T>> QueryAsync<T>(string sql, object parameters)
    {
        // Validate tenant context exists
        var tenantContext = _contextManager.GetCurrentTenant();
        if (tenantContext == null)
            throw new InvalidOperationException("No tenant context available");

        // Validate query respects tenant boundaries
        await _queryValidator.ValidateQueryAsync(sql, tenantContext.TenantId);

        // Get tenant-specific connection
        using var connection = await _connectionFactory.GetTenantConnectionAsync(
            tenantContext.TenantId);

        // Execute query with audit logging
        var result = await connection.QueryAsync<T>(sql, parameters);

        await _auditLogger.LogDataAccessAsync(
            tenantContext.TenantId,
            sql,
            result.Count(),
            DateTime.UtcNow);

        return result;
    }
}
```text

**Step 2.3: Implement Encryption Service**

Create tenant-specific encryption with key management:

```csharp
public class TenantEncryptionService
{
    private readonly IKeyManagementService _keyManagement;

    public async Task<byte[]> EncryptAsync(string tenantId, byte[] data)
    {
        // Retrieve tenant-specific encryption key
        var key = await _keyManagement.GetTenantKeyAsync(tenantId);

        // Encrypt data using AES256
        using var aes = Aes.Create();
        aes.Key = key.KeyMaterial;
        aes.GenerateIV();

        using var encryptor = aes.CreateEncryptor();
        var encryptedData = encryptor.TransformFinalBlock(data, 0, data.Length);

        // Prepend IV to encrypted data
        var result = new byte[aes.IV.Length + encryptedData.Length];
        Buffer.BlockCopy(aes.IV, 0, result, 0, aes.IV.Length);
        Buffer.BlockCopy(encryptedData, 0, result, aes.IV.Length, encryptedData.Length);

        return result;
    }
}
