### Configuration Examples

**Database-per-Tenant Configuration**:

```json
{
  "TenantIsolation": {
    "Strategy": "DatabasePerTenant",
    "Provisioning": {
      "DatabaseServer": "medicaid-sql-server.database.windows.net",
      "AdminConnectionString": "Server=...;Database=master;...",
      "NamingPattern": "tenant_{tenantId}_db",
      "InitializationScript": "scripts/tenant-init.sql"
    },
    "Encryption": {
      "Algorithm": "AES256",
      "KeyRotationDays": 90,
      "KeyManagementService": "Azure Key Vault"
    },
    "Backup": {
      "RetentionDays": 30,
      "GeoRedundant": true,
      "Schedule": "0 2 * * *"
    }
  }
}
```text

**Schema-per-Tenant Configuration**:

```json
{
  "TenantIsolation": {
    "Strategy": "SchemaPerTenant",
    "SharedDatabase": {
      "ConnectionString": "Server=shared-db.database.windows.net;Database=multi_tenant;...",
      "SchemaNamingPattern": "tenant_{tenantId}",
      "MaxTenantsPerDatabase": 100
    },
    "QueryModification": {
      "AutomaticSchemaQualification": true,
      "ValidationMode": "Strict"
    }
  }
}
